const cases = $input.all();
const now = new Date();
const alerts = [];
const deindexQueue = [];
const dmcaQueue = [];
const escalationQueue = [];
const socialReportQueue = [];

for (const item of cases) {
  const c = item.json;

  // Deadline alerts
  if (c.deadline_date) {
    const daysUntil = Math.ceil((new Date(c.deadline_date) - now) / 86400000);
    if (daysUntil <= 7 && daysUntil > 0) {
      alerts.push({
        case_id: c.id,
        case_number: c.case_number,
        alert_type: daysUntil <= 3 ? 'urgent' : 'warning',
        message: `Case ${c.case_number} deadline in ${daysUntil} days`
      });
    }
  }

  // Auto de-index: if evidence returns 404 (verified removed)
  if (c.source_url && c.verification_status === 'removed') {
    deindexQueue.push({ url: c.source_url, case_id: c.id });
  }

  // Auto DMCA via Social Enforcer: if evidence is still live and case is open > 3 days
  if (c.source_url && c.verification_status !== 'removed' && c.status === 'open') {
    const created = new Date(c.created_at || now);
    const daysSinceOpen = Math.ceil((now - created) / 86400000);
    if (daysSinceOpen > 3) {
      dmcaQueue.push({ url: c.source_url, case_id: c.id, case_number: c.case_number });
    }
    // Escalation: if DMCA was already sent > 5 days ago and content is still live
    if (daysSinceOpen > 5 && (c.escalation_level || 0) < 3) {
      try {
        const domain = new URL(c.source_url).hostname;
        escalationQueue.push({ domain, case_id: c.id, current_level: c.escalation_level || 0 });
      } catch(e) {}
    }
  }

  // Social media impersonator/content reports
  const platform = (c.source_platform || '').toLowerCase();
  const socialPlatforms = ['reddit','twitter','x','tiktok','instagram','facebook','telegram'];
  if (socialPlatforms.includes(platform) && c.source_url) {
    socialReportQueue.push({
      platform: platform === 'x' ? 'twitter' : platform,
      content_url: c.source_url,
      report_type: c.is_impersonator ? 'impersonator' : 'copyright',
      creator_name: c.creator_name || 'Unknown Creator',
      case_id: c.id
    });
  }
}

return [{ json: { alerts, deindexQueue, dmcaQueue, escalationQueue, socialReportQueue } }];

const data = $input.first().json;
const items = data.deindexQueue || [];
return items.map(i => ({ json: i }));

const data = $input.first().json;
const items = data.dmcaQueue || [];
return items.map(i => ({ json: i }));

const data = $input.first().json;
const items = data.escalationQueue || [];
return items.map(i => ({ json: i }));

const data = $input.first().json;
const items = data.socialReportQueue || [];
return items.map(i => ({ json: i }));

const data = $input.first().json;
const alerts = data.alerts || [];
if (alerts.length === 0) return [];
const report = {
  report_date: new Date().toISOString(),
  report_type: 'legal_compliance_daily',
  total_alerts: alerts.length,
  urgent_count: alerts.filter(a => a.alert_type === 'urgent').length,
  deindex_submitted: (data.deindexQueue || []).length,
  dmca_submitted: (data.dmcaQueue || []).length,
  alerts,
  summary: `${alerts.length} deadline alerts, ${(data.deindexQueue || []).length} de-index requests, ${(data.dmcaQueue || []).length} DMCA notices`
};
return [{ json: report }];

// Validate webhook authentication
const headers = $input.first().json.headers;
const expectedToken = $env.N8N_WEBHOOK_AUTH_TOKEN;
const authHeader = $env.N8N_WEBHOOK_AUTH_HEADER || 'X-Lysis-Auth';

const receivedToken = headers[authHeader.toLowerCase()] || headers[authHeader];

if (!expectedToken) {
  throw new Error('N8N_WEBHOOK_AUTH_TOKEN not configured');
}

if (!receivedToken || receivedToken !== expectedToken) {
  throw new Error('Unauthorized: Invalid or missing auth token');
}

return $input.first().json;
